# Alpine mkimage profile for the BeagleBoard-xM (DM3730) audio appliance.
# Same as the PandaBoard's, except that extlinux uses FDTDIR: U-Boot's findfdt
# sets ${fdtfile} for the xM revision (board.conf DTB is empty).
# Loaded by aports/scripts/mkimage.sh from ~/.mkimage, where
# scripts/build-image.sh copies it together with board.conf, appliance.conf,
# packages.list and the apkovl generator. The output tarball is unpacked onto
# the SD card's FAT partition; U-Boot is written raw by
# boards/beaglexm/write-sdcard.sh.

beaglexm_extlinux_gen() {
	cat <<-EOF
	# Generated by mkimg.beaglexm.sh
	DEFAULT $KERNEL_FLAVOR
	TIMEOUT 10
	LABEL $KERNEL_FLAVOR
	MENU LABEL Alpine Linux ($KERNEL_FLAVOR)
	KERNEL /boot/vmlinuz-$KERNEL_FLAVOR
	INITRD /boot/initramfs-$KERNEL_FLAVOR
	FDTDIR /boot/dtbs-$KERNEL_FLAVOR
	APPEND $initfs_cmdline $kernel_cmdline
	EOF
}

build_beaglexm_extlinux() {
	mkdir -p "$DESTDIR"/extlinux
	beaglexm_extlinux_gen > "$DESTDIR"/extlinux/extlinux.conf
}

section_beaglexm_extlinux() {
	[ -n "$beaglexm_extlinux" ] || return 0
	build_section beaglexm_extlinux $(beaglexm_extlinux_gen | checksum)
}

profile_beaglexm() {
	profile_base
	. "$HOME"/.mkimage/board.conf
	. "$HOME"/.mkimage/appliance.conf
	title="$BOARD_NAME"
	desc="Diskless Alpine for the $BOARD_NAME audio appliance."
	image_ext="tar.gz"
	arch="$ALPINE_ARCH"
	kernel_flavors="$KERNEL_FLAVOR"
	kernel_addons=
	initfs_features="base mmc squashfs usb"
	# No "quiet": the boot log on serial is the main debugging tool.
	initfs_cmdline="modules=loop,squashfs,sd-mod,usb-storage"
	kernel_cmdline="console=$CONSOLE"
	modloopfw="$MODLOOP_EXTRA_FIRMWARE"
	beaglexm_extlinux=yes
	# U-Boot + extlinux boot; no GRUB/EFI (profile_base enables it for ARM).
	grub_mod=
	apks="$(sed 's/#.*//' "$HOME"/.mkimage/packages.list) $BOARD_PACKAGES"
	apkovl="genapkovl.sh"
	hostname="$HOSTNAME"
}
